function buildColumns(): Col[] {
  const cols: Col[] = [];
  const add = (key: string, label: string, group: string, fmt: CellFormat, tip: string) => { cols.push({ key, label, group, fmt, tip }); };
  add('pe', 'P/E', 'Valuation', 'x', 'P/E - price divided by trailing twelve month earnings per share (Yahoo Finance snapshot). Unavailable for loss makers and for ADRs whose reporting currency differs from the price currency.');
  add('forwardPe', 'Fwd P/E', 'Valuation', 'x', 'Forward P/E - price divided by the analyst consensus EPS estimate for the next fiscal year (Yahoo Finance).');
  add('ps', 'P/S', 'Valuation', 'x', 'P/S - market cap divided by trailing twelve month revenue.');
  add('forwardPs', 'Fwd P/S', 'Valuation', 'x', 'Forward P/S - market cap divided by the analyst consensus revenue estimate for the next fiscal year.');
  add('pFcf', 'P/FCF', 'Valuation', 'x', 'P/FCF - market cap divided by trailing twelve month free cash flow. Blank when free cash flow is not positive.');
  add('evEbitda', 'EV/EBITDA', 'Valuation', 'x', 'EV/EBITDA - enterprise value divided by trailing twelve month EBITDA (Yahoo Finance).');
  add('fcfToEbitda', 'FCF/EBITDA', 'Valuation', 'pct', 'FCF/EBITDA - cash conversion: trailing twelve month free cash flow as a percentage of EBITDA.');
  add('pb', 'P/B', 'Valuation', 'x', 'P/B - price divided by book value per share.');
  add('dividendYield', 'Dividend Yield', 'Dividends', 'pct', 'Dividend Yield - dividends paid over the last 12 months divided by the last close. 0% means no payments in the last year.');
  add('dividendGrowth', 'Div Growth 1Y', 'Dividends', 'pct', 'Dividend per share growth of the last complete calendar year over the year before (sum of ex-dates, split adjusted).');
  add('dividendGrowth3y', 'Div Growth 3Y', 'Dividends', 'pct', 'Dividend per share CAGR over 3 complete calendar years.');
  add('dividendGrowth5y', 'Div Growth 5Y', 'Dividends', 'pct', 'Dividend per share CAGR over 5 complete calendar years.');
  add('payoutRatio', 'Payout Ratio', 'Dividends', 'pct', 'Payout Ratio - dividends paid (cash flow statement) divided by net income of the latest fiscal year.');
  add('fcfPayout', 'FCF Payout', 'Dividends', 'pct', 'FCF Payout - dividends paid divided by free cash flow of the latest fiscal year. Blank when free cash flow is not positive.');
  add('quickRatio', 'Quick Ratio', 'Balance sheet', 'x', 'Quick Ratio - (cash and short-term investments + receivables) / current liabilities at the latest fiscal year end.');
  add('currentRatio', 'Current Ratio', 'Balance sheet', 'x', 'Current Ratio - current assets / current liabilities at the latest fiscal year end.');
  add('debtToEquity', 'D/E', 'Balance sheet', 'x', 'Debt to Equity - total debt / shareholders equity at the latest fiscal year end. Blank when equity is not positive.');
  add('netDebtToEbitda', 'NetDebt/EBITDA', 'Balance sheet', 'x', 'Net Debt / EBITDA - (total debt - cash, short-term and long-term investments) / EBITDA. Negative means net cash. Blank when EBITDA is not positive.');
  add('roic', 'ROIC', 'Balance sheet', 'pct', 'ROIC - operating income after tax divided by average invested capital (debt + equity - cash).');
  [['Growth 1Y', '', '1Y'], ['Growth 3Y CAGR', '3y', '3Y'], ['Growth 5Y CAGR', '5y', '5Y']].forEach(([group, suffix, tag]) => {
    GROWTH_NAMES.forEach(([name, label, what]) => {
      const tip = suffix
        ? `${label} Growth ${tag} - compound annual growth rate of ${what} over ${suffix.replace('y', '')} fiscal years. Blank when an endpoint is not positive.`
        : `${label} Growth 1Y - change of ${what} over the previous fiscal year, relative to the absolute previous value.`;
      add(`${name}Growth${suffix}`, `${label} ${tag}`, group, 'pct', tip);
    });
  });
  MARGIN_NAMES.forEach(([key, label, what]) => add(key, label, 'Margins', 'pct', `${label} - ${what}, latest fiscal year.`));
  [['Margin change 1Y', '', '1Y'], ['Margin change 3Y', '3y', '3Y']].forEach(([group, suffix, tag]) => {
    MARGIN_NAMES.forEach(([key, label]) => {
      add(`${key}Delta${suffix.replace('y', 'y')}`, `${label.replace(' Margin', '')} Δ ${tag}`, group, 'pp', `${label} change in percentage points versus ${tag === '1Y' ? 'the previous' : '3 fiscal years earlier'} fiscal year.`);
    });
  });
  [['perfYtd', 'YTD'], ['perf1y', '1Y'], ['perf3y', '3Y'], ['perf5y', '5Y'], ['perf10y', '10Y']].forEach(([key, tag]) => {
    add(key, `Perf ${tag}`, 'Performance', 'pct', `Performance ${tag} - cumulative price change from unadjusted closes (dividends not included).`);
  });
  [['ytd', 'YTD Return', 'YTD'], ['tr1y', 'TR 1Y', '1-year'], ['tr3y', 'TR 3Y', '3-year'], ['tr5y', 'TR 5Y', '5-year'], ['tr10y', 'TR 10Y', '10-year']].forEach(([key, label, tag]) => {
    add(key, label, 'Total return', 'pct', `${label} - cumulative ${tag} total return from dividend- and split-adjusted closes.`);
  });
  [['cagr3y', 'CAGR 3Y'], ['cagr5y', 'CAGR 5Y'], ['cagr10y', 'CAGR 10Y'], ['siAnn', 'SI Ann.']].forEach(([key, label]) => {
    add(key, label, 'Total return', 'pct', key === 'siAnn' ? 'Since-listing annualized total return over the available price history.' : `${label} - annualized total return.`);
  });
  add('enterpriseValue', 'EV', 'Market', 'money', 'Enterprise Value - market cap plus debt minus cash (Yahoo Finance).');
  add('beta', 'Beta', 'Market', 'x', 'Beta - sensitivity to the market (Yahoo Finance, 5-year monthly).');
  add('week52High', '52W High', 'Market', 'price', '52-week high price.');
  add('week52Low', '52W Low', 'Market', 'price', '52-week low price.');
  add('sharesOutstanding', 'Shares', 'Market', 'int', 'Shares outstanding.');
  add('basisCls', 'Source', 'Data', 'basis', 'Source of the fundamentals: SEC = EDGAR XBRL annual filings; SEC+Y = SEC with gaps filled from Yahoo; Yahoo = Yahoo annual statements only. Hover a badge for the full text.');
  add('fyTs', 'FY As Of', 'Data', 'date', 'fundamentalsAsOf - the end of the latest fiscal year the fundamentals describe.');
  add('perfTs', 'Return As Of', 'Data', 'date', 'performanceAsOf - the date of the last price the returns are calculated as of.');
  return cols;
}

